import{_ as e,o,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"🛠️ 技术栈","description":"后端:FastAPI + Python 3.12 + uv","frontmatter":{},"headers":[],"relativePath":"agent/学习计划/项目C-端到端应用/15-tech-stack.md","filePath":"agent/学习计划/项目C-端到端应用/15-tech-stack.md","lastUpdated":1793932732000}'),n={name:"agent/学习计划/项目C-端到端应用/15-tech-stack.md"};function a(i,t,l,c,g,p){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="🛠️-技术栈" tabindex="-1">🛠️ 技术栈 <a class="header-anchor" href="#🛠️-技术栈" aria-label="Permalink to &quot;🛠️ 技术栈&quot;">​</a></h1><p>项目使用:</p><ul><li><strong>后端</strong>:FastAPI + Python 3.12 + uv</li><li><strong>数据库</strong>:PostgreSQL + SQLAlchemy 2.x + Alembic(迁移)</li><li><strong>鉴权</strong>:JWT(Access + Refresh 双 token)</li><li><strong>文件存储</strong>:本地磁盘起步,可替换为对象存储</li><li><strong>向量库</strong>:ChromaDB / pgvector(按部署形态二选一)</li><li><strong>LLM</strong>:默认 MiniMax-M3(兼容 OpenAI 协议)</li><li><strong>容器</strong>:Docker + docker-compose</li><li><strong>CI/CD</strong>:GitHub Actions(测试 → 构建镜像 → 部署)</li><li><strong>前端</strong>:Next.js(App Router)+ TypeScript</li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>技术栈:<strong>Python + FastAPI + LangGraph + LangChain + pgvector/Postgres + SQLAlchemy/Alembic + JWT + Docker + GitHub Actions + React/Next.js 前端</strong>。</li><li>选型逻辑:<strong>能合并的系统就合并</strong>(pgvector 替代独立向量库)、<strong>能托管的就托管</strong>(模型走 API)。</li><li>前端用你熟悉的栈做<strong>会话管理、流式对话、引用溯源、进度与审批 UI</strong>。</li><li>部署形态:后端容器 + 前端静态托管 + Postgres(托管服务如 Neon/Supabase)。</li><li>监控用 OpenTelemetry + Grafana,或先用结构化日志 + 简单看板。</li><li>面试加分:能讲清「<strong>每个组件为什么选它、生产环境会怎么换</strong>」,这是架构成熟度的直接体现。</li></ul>',5)])])}const d=e(n,[["render",a]]);export{_ as __pageData,d as default};
